221	const inflightGets = new Map<string, Promise<unknown>>();
222	
223	async function request<T>(path: string, init?: RequestInit): Promise<T> {
224	  const method = init?.method ?? "GET";
225	
226	  // Deduplicate identical in-flight GET requests (React StrictMode fires
227	  // useEffect twice in dev mode, producing redundant fetches).
228	  if (method === "GET" && !init?.body) {
229	    const existing = inflightGets.get(path);
230	    if (existing) return existing as Promise<T>;
231	
232	    const promise = doRequest<T>(path, init).finally(() => {
233	      inflightGets.delete(path);
234	    });
235	    inflightGets.set(path, promise);
236	    return promise;
237	  }
238	
239	  return doRequest<T>(path, init);
240	}
241	
242	async function doRequest<T>(path: string, init?: RequestInit): Promise<T> {
243	  const requestId = crypto.randomUUID();
244	  const start = performance.now();
245	
246	  const res = await fetch(path, {
247	    ...init,
248	    headers: {
249	      Accept: "application/json",
250	      "X-Request-Id": requestId,
251	      "X-Session-Id": SESSION_ID,
252	      ...(init?.body ? { "Content-Type": "application/json" } : {}),
253	      ...(init?.headers ?? {}),
254	    },
255	  });
256	
257	  const latencyMs = Math.round(performance.now() - start);
258	  const method = init?.method ?? "GET";
259	
260	  if (!res.ok) {
261	    const text = await res.text().catch(() => "");
262	    logger.error("http", `${method} ${path} → ${res.status}`, {
263	      requestId,
264	      latencyMs,
265	      status: res.status,
266	      body: text.slice(0, 200),
267	    });
268	    throw new Error(`${res.status} ${res.statusText}: ${text}`);
269	  }
270	
271	  logger.debug("http", `${method} ${path} → ${res.status}`, {
272	    requestId,
273	    latencyMs,
274	    status: res.status,
275	  });
276	
277	  return (await res.json()) as T;
278	}
