72	/** Best-effort: render any tool output into a single string. */
73	export function extractOutputText(output: unknown): string {
74	  if (!output) return "";
75	  if (typeof output === "string") return output;
76	  if (Array.isArray(output)) {
77	    return output
78	      .map((x) =>
79	        x && typeof x === "object" && typeof (x as Record<string, unknown>).text === "string"
80	          ? ((x as Record<string, unknown>).text as string)
81	          : typeof x === "string" ? x : "",
82	      )
83	      .filter(Boolean)
84	      .join("\n");
85	  }
86	  if (typeof output === "object") {
87	    const o = output as Record<string, unknown>;
88	    if (typeof o.text === "string") return o.text;
89	    if (typeof o.content === "string") return o.content;
90	    if (Array.isArray(o.content)) return extractOutputText(o.content);
91	    try {
92	      return JSON.stringify(o, null, 2);
93	    } catch {
94	      return String(o);
95	    }
96	  }
97	  return String(output);
98	}
