3	export function pairToolResults(messages: Message[]) {
4	  const allResults = new Map<string, Message[]>();
5	  for (const m of messages) {
6	    if (m.role === "tool_result" && m.toolUseId) {
7	      const arr = allResults.get(m.toolUseId);
8	      if (arr) arr.push(m);
9	      else allResults.set(m.toolUseId, [m]);
10	    }
11	  }
12	  const resultByToolUseId = new Map<string, Message>();
13	  for (const [tuId, results] of allResults) {
14	    resultByToolUseId.set(
15	      tuId,
16	      results.find((r) => r.toolStatus !== "error") ??
17	        results[results.length - 1],
18	    );
19	  }
20	  const hiddenIds = new Set<string>();
21	  for (const m of messages) {
22	    if (m.role === "tool_use" && m.toolUseId && allResults.has(m.toolUseId)) {
23	      for (const r of allResults.get(m.toolUseId)!) hiddenIds.add(r.id);
24	    }
25	  }
26	  return { resultByToolUseId, hiddenIds };
27	}
