14	export interface TurnEntry {
15	  /** Zero-based turn index; equals position in the returned array. */
16	  index: number;
17	  /** The user message that opens this turn. May be undefined for sessions
18	   *  that start with a system / assistant message (very rare). */
19	  userMessage?: Message;
20	  /** Index of `userMessage` in the original messages array, or -1. */
21	  userMessageIndex: number;
22	  /** Concise label — first line of the user prompt, ≤ 60 chars. */
23	  preview: string;
24	  /** Total messages belonging to this turn (user + assistant + tools). */
25	  messageCount: number;
26	  /** Tool-use messages count, for the per-turn chip. */
27	  toolCount: number;
28	  /** True if any message in this turn is a tool with toolStatus === "error". */
29	  hasError: boolean;
30	  /** Number of subagent (Task/Agent) tool_use calls in this turn. */
31	  subagentCount: number;
32	}
33	
34	/** Split the message stream into turns. */
35	export function buildTurns(messages: Message[]): TurnEntry[] {
36	  const turns: TurnEntry[] = [];
37	  let cur: TurnEntry | null = null;
38	
39	  for (let i = 0; i < messages.length; i++) {
40	    const m = messages[i];
41	    // System / meta lines at the very start get swept into a "turn 0".
42	    if (m.role === "user") {
43	      cur = {
44	        index: turns.length,
45	        userMessage: m,
46	        userMessageIndex: i,
47	        preview: previewOf(m.text || ""),
48	        messageCount: 1,
49	        toolCount: 0,
50	        hasError: false,
51	        subagentCount: 0,
52	      };
53	      turns.push(cur);
54	      continue;
55	    }
56	
57	    if (!cur) {
58	      // No user message yet — bucket leading system / assistant in a synthetic
59	      // turn 0 so the sidebar still shows them.
60	      cur = {
61	        index: turns.length,
62	        userMessage: undefined,
63	        userMessageIndex: -1,
64	        preview: "(系统消息)",
65	        messageCount: 0,
66	        toolCount: 0,
67	        hasError: false,
68	        subagentCount: 0,
69	      };
70	      turns.push(cur);
71	    }
72	
73	    cur.messageCount++;
74	    if (m.role === "tool_use") {
75	      cur.toolCount++;
76	      if (canonicalTool(m.toolName) === "Task") cur.subagentCount++;
77	    }
78	    if (m.role === "tool_result" && m.toolStatus === "error") cur.hasError = true;
79	  }
80	
81	  return turns;
82	}
83	
84	/**
85	 * Given a message index in the original messages array, return the turn
86	 * index it belongs to. Uses the fact that turns are sorted by
87	 * userMessageIndex — the message belongs to the last turn whose
88	 * userMessageIndex <= msgIndex.
89	 */
90	export function turnIndexForMessage(
91	  turns: TurnEntry[],
92	  msgIndex: number,
93	): number {
94	  let best = 0;
95	  for (let i = 0; i < turns.length; i++) {
96	    const start = turns[i]!.userMessageIndex === -1 ? 0 : turns[i]!.userMessageIndex;
97	    if (start <= msgIndex) best = i;
98	    else break;
99	  }
100	  return best;
101	}
102	
103	function previewOf(text: string): string {
104	  // cleanupPromptPreview strips Cursor's <user_query>…</user_query>
105	  // wrapper, Claude Code's <command-message>/<command-name> envelopes,
106	  // and friends — without that, every Cursor turn label looks like
107	  // "<user_query>" because the wrapper is the literal first line.
108	  return cleanupPromptPreview(text, 60);
109	}
