1	import { useEffect, useState } from "react";
2	
3	export interface AsyncState<T> {
4	  data: T | null;
5	  loading: boolean;
6	  error: Error | null;
7	  refetch: () => void;
8	}
9	
10	export function useAsync<T>(fn: () => Promise<T>, deps: unknown[] = []): AsyncState<T> {
11	  const [data, setData] = useState<T | null>(null);
12	  const [loading, setLoading] = useState(true);
13	  const [error, setError] = useState<Error | null>(null);
14	  const [tick, setTick] = useState(0);
15	
16	  useEffect(() => {
17	    let cancelled = false;
18	    setLoading(true);
19	    setError(null);
20	    fn()
21	      .then((v) => {
22	        if (!cancelled) {
23	          setData(v);
24	          setError(null);
25	        }
26	      })
27	      .catch((e) => {
28	        if (!cancelled) setError(e instanceof Error ? e : new Error(String(e)));
29	      })
30	      .finally(() => {
31	        if (!cancelled) setLoading(false);
32	      });
33	    return () => {
34	      cancelled = true;
35	    };
36	    // eslint-disable-next-line react-hooks/exhaustive-deps
37	  }, [...deps, tick]);
38	
39	  return { data, loading, error, refetch: () => setTick((t) => t + 1) };
40	}
41	
42	/**
43	 * SWR-style cache layer for `useAsync`. Backed by a module-level
44	 * `Map` keyed by a caller-supplied string. When the same key shows
45	 * up again (e.g. user navigates away to a detail page and comes
46	 * back), the hook *immediately* returns the previously fetched
47	 * value while a fresh fetch happens in the background. This kills
48	 * the "everything blanks out for a beat" feeling that plain
49	 * `useAsync` produces on every remount.
50	 *
51	 * Notes:
52	 *  - Cache survives unmount but not full page reloads.
53	 *  - `loading` reports `true` only on the very first fetch for a
54	 *    key — subsequent revalidations don't flip it back to true so
55	 *    the UI doesn't disappear behind a spinner.
56	 *  - Errors are NOT cached; a failed revalidation surfaces in
57	 *    `error` while keeping the stale `data` visible.
58	 */
59	const asyncCache = new Map<string, { data: unknown; at: number }>();
60	
61	export function useCachedAsync<T>(
62	  key: string,
63	  fn: () => Promise<T>,
64	  deps: unknown[] = [],
65	): AsyncState<T> {
66	  const cached = asyncCache.get(key);
67	  const [data, setData] = useState<T | null>(
68	    cached ? (cached.data as T) : null,
69	  );
70	  // First fetch for this key shows a spinner; revalidations don't.
71	  const [loading, setLoading] = useState(!cached);
72	  const [error, setError] = useState<Error | null>(null);
73	  const [tick, setTick] = useState(0);
74	
75	  useEffect(() => {
76	    let cancelled = false;
77	    const hadCache = asyncCache.has(key);
78	    if (!hadCache) setLoading(true);
79	    fn()
80	      .then((v) => {
81	        if (cancelled) return;
82	        asyncCache.set(key, { data: v, at: Date.now() });
83	        setData(v);
84	        setError(null);
85	      })
86	      .catch((e) => {
87	        if (!cancelled) setError(e instanceof Error ? e : new Error(String(e)));
88	      })
89	      .finally(() => {
90	        if (!cancelled) setLoading(false);
91	      });
92	    return () => {
93	      cancelled = true;
94	    };
95	    // eslint-disable-next-line react-hooks/exhaustive-deps
96	  }, [key, ...deps, tick]);
97	
98	  return { data, loading, error, refetch: () => setTick((t) => t + 1) };
99	}
100	
101	/** Drop cached values. Pass:
102	 *   - nothing → clear everything
103	 *   - exact key string → drop only that key
104	 *   - { prefix } → drop every key starting with the prefix (handy
105	 *     when keys embed search/filter values, e.g. dropping
106	 *     "sessions:list" should clear all variants regardless of which
107	 *     query was last fetched).
108	 *  Used after a mutation where waiting for the natural revalidate
109	 *  cycle would surface stale data. */
110	export function invalidateAsyncCache(arg?: string | { prefix: string }) {
111	  if (arg === undefined) {
112	    asyncCache.clear();
113	    return;
114	  }
115	  if (typeof arg === "string") {
116	    asyncCache.delete(arg);
117	    return;
118	  }
119	  const { prefix } = arg;
120	  for (const k of Array.from(asyncCache.keys())) {
121	    if (k.startsWith(prefix)) asyncCache.delete(k);
122	  }
123	}
124	
125	export function useDebounced<T>(value: T, delay = 200): T {
126	  const [debounced, setDebounced] = useState(value);
127	  useEffect(() => {
128	    const id = setTimeout(() => setDebounced(value), delay);
129	    return () => clearTimeout(id);
130	  }, [value, delay]);
131	  return debounced;
132	}
