1	import { xmlTagRegistry } from "./xml-tag-registry";
2	
3	export interface XmlSection {
4	  tag: string;
5	  content: string;
6	}
7	
8	export interface ParsedXmlBlock {
9	  attrs: Record<string, string>;
10	  sections: XmlSection[];
11	}
12	
13	export interface ParsedXmlTag {
14	  tagName: string;
15	  attrs: Record<string, string>;
16	  sections: XmlSection[];
17	  blocks: ParsedXmlBlock[];
18	  raw: string;
19	}
20	
21	const TAG_RE = /<([\w-]+)>([\s\S]*?)<\/\1>/g;
22	const ATTR_RE = /([\w-]+)="([^"]*)"/g;
23	
24	export function detectXmlTag(text: string): string | null {
25	  if (!text || text[0] !== "<") return null;
26	  const m = text.match(/^<([\w-]+)[\s>]/);
27	  if (!m) return null;
28	  const tag = m[1];
29	  return xmlTagRegistry[tag] ? tag : null;
30	}
31	
32	function parseAttrs(openTag: string): Record<string, string> {
33	  const attrs: Record<string, string> = {};
34	  let m: RegExpExecArray | null;
35	  const re = new RegExp(ATTR_RE.source, "g");
36	  while ((m = re.exec(openTag)) !== null) {
37	    attrs[m[1]] = m[2];
38	  }
39	  return attrs;
40	}
41	
42	export function parseXmlTag(text: string): ParsedXmlTag | null {
43	  const tagName = detectXmlTag(text);
44	  if (!tagName) return null;
45	
46	  const blocks = parseAllBlocks(text, tagName);
47	  if (blocks.length === 0) return null;
48	
49	  return {
50	    tagName,
51	    attrs: blocks[0].attrs,
52	    sections: blocks[0].sections,
53	    blocks,
54	    raw: text,
55	  };
56	}
57	
58	function parseSingleBlock(inner: string): XmlSection[] {
59	  const sections: XmlSection[] = [];
60	  let lastEnd = 0;
61	  const re = new RegExp(TAG_RE.source, "g");
62	  let match: RegExpExecArray | null;
63	
64	  while ((match = re.exec(inner)) !== null) {
65	    if (match.index > lastEnd) {
66	      const gap = inner.slice(lastEnd, match.index).trim();
67	      if (gap) sections.push({ tag: "__text__", content: gap });
68	    }
69	    sections.push({ tag: match[1], content: match[2].trim() });
70	    lastEnd = match.index + match[0].length;
71	  }
72	
73	  if (lastEnd < inner.length) {
74	    const tail = inner.slice(lastEnd).trim();
75	    if (tail) sections.push({ tag: "__text__", content: tail });
76	  }
77	
78	  if (sections.length === 0 && inner.trim()) {
79	    sections.push({ tag: "__text__", content: inner.trim() });
80	  }
81	
82	  return sections;
83	}
84	
85	function parseAllBlocks(text: string, tagName: string): ParsedXmlBlock[] {
86	  const blockRe = new RegExp(
87	    `<${tagName}([^>]*)>([\\s\\S]*?)<\\/${tagName}>`,
88	    "g",
89	  );
90	  const blocks: ParsedXmlBlock[] = [];
91	  let match: RegExpExecArray | null;
92	
93	  while ((match = blockRe.exec(text)) !== null) {
94	    blocks.push({
95	      attrs: parseAttrs(match[1]),
96	      sections: parseSingleBlock(match[2].trim()),
97	    });
98	  }
99	
100	  return blocks;
101	}
