1	import { createElement } from "react";
2	import { highlightSegments } from "@/lib/highlight-shared";
3	import type { ReactNode } from "react";
4	
5	const MARK_BASE = "search-mark bg-amber-300/40 text-fg rounded px-0.5";
6	
7	/**
8	 * Render text with query matches wrapped in <mark class="search-mark"> elements.
9	 * All marks carry the `search-mark` class so the detail view can query & navigate.
10	 */
11	export function HighlightText({
12	  text,
13	  q,
14	  className,
15	}: {
16	  text: string;
17	  q?: string;
18	  className?: string;
19	}): ReactNode {
20	  if (!q || !q.trim() || !text) return text;
21	  const segs = highlightSegments(text, q);
22	  if (segs.length === 1 && segs[0]!.type === "text") return text;
23	  return segs.map((seg, i) =>
24	    seg.type === "mark"
25	      ? createElement("mark", { key: i, className: className ?? MARK_BASE }, seg.value)
26	      : seg.value
27	  );
28	}
29	
30	export function highlightJsx(text: string, q?: string): ReactNode {
31	  return HighlightText({ text, q });
32	}
33	
34	export interface HighlightDomResult {
35	  /** Total match count, computed from DOM walk */
36	  count: number;
37	  /** Remove all marks and restore original DOM */
38	  cleanup: () => void;
39	}
40	
41	/**
42	 * Apply DOM-level text highlighting on an already-rendered container element.
43	 * Walks all TEXT_NODE descendants, wraps matching substrings in <mark> elements
44	 * with class `search-mark` so the parent can query them later for navigation.
45	 *
46	 * Does NOT manage active/focused state — that's the caller's job, so it can
47	 * coordinate focus across multiple messages in a virtualized list.
48	 */
49	export function highlightDom(container: HTMLElement, q: string): HighlightDomResult {
50	  const empty: HighlightDomResult = { count: 0, cleanup: () => {} };
51	  if (!q || !q.trim() || !container) return empty;
52	  const ql = q.toLowerCase();
53	  const marks: HTMLElement[] = [];
54	
55	  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT, null);
56	  const textNodes: Text[] = [];
57	  while (walker.nextNode()) {
58	    textNodes.push(walker.currentNode as Text);
59	  }
60	
61	  for (const node of textNodes) {
62	    const text = node.textContent ?? "";
63	    const tl = text.toLowerCase();
64	    let searchFrom = 0;
65	    const ranges: Array<{ start: number; end: number }> = [];
66	    while (searchFrom < tl.length) {
67	      const idx = tl.indexOf(ql, searchFrom);
68	      if (idx < 0) break;
69	      ranges.push({ start: idx, end: idx + ql.length });
70	      searchFrom = idx + ql.length;
71	    }
72	    if (ranges.length === 0) continue;
73	
74	    for (let i = ranges.length - 1; i >= 0; i--) {
75	      const { start, end } = ranges[i]!;
76	      const range = document.createRange();
77	      range.setStart(node, start);
78	      range.setEnd(node, end);
79	      const mark = document.createElement("mark");
80	      mark.className = MARK_BASE;
81	      try {
82	        range.surroundContents(mark);
83	        marks.push(mark);
84	      } catch {
85	        // surroundContents can fail if range crosses element boundaries; skip.
86	      }
87	    }
88	  }
89	
90	  const cleanup = () => {
91	    for (const mark of marks) {
92	      const parent = mark.parentNode;
93	      if (!parent) continue;
94	      while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
95	      parent.removeChild(mark);
96	    }
97	    container.normalize();
98	  };
99	
100	  return { count: marks.length, cleanup };
101	}
102	
103	/**
104	 * Scroll a given mark element into the center of its nearest scrollable ancestor
105	 * without triggering whole-page scrolls (which break inside Drawers).
106	 */
107	export function centerMarkInScroller(mark: HTMLElement): void {
108	  let node: HTMLElement | null = mark.parentElement;
109	  let scroller: HTMLElement | null = null;
110	  while (node) {
111	    const style = getComputedStyle(node);
112	    if (
113	      (style.overflowY === "auto" || style.overflowY === "scroll") &&
114	      node.scrollHeight > node.clientHeight
115	    ) {
116	      scroller = node;
117	      break;
118	    }
119	    node = node.parentElement;
120	  }
121	  if (!scroller) return;
122	  const markRect = mark.getBoundingClientRect();
123	  const scrollerRect = scroller.getBoundingClientRect();
124	  const desiredScrollTop =
125	    scroller.scrollTop +
126	    (markRect.top - scrollerRect.top) -
127	    scrollerRect.height / 2 +
128	    markRect.height / 2;
129	  scroller.scrollTo({ top: desiredScrollTop, behavior: "smooth" });
130	}
